// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 fees, address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));

        // Make c hold some ERC20 tokens so the transfer has something to move
        MockERC20 token = new MockERC20();
        token.mint(address(c), fees);

        // Make c the owner and configure an unclaimed fee balance for that asset
        vm.startPrank(address(this)); // test contract is owner (deployed c)
        c.withdrawFees(address(token), recipient); // clear any pre-existing (0)
        vm.stopPrank();

        // Seed unclaimedFees[asset] on c by directly transferring tokens in then calling withdrawFees.
        // We rely on the public surface: unclaimedFees is a getter, withdrawFees is onlyOwner.
        // The owner can set the fee and then we can set the unclaimedFees by calling withdrawFees? No.
        // Instead: use the fact that c.withdrawFees reads unclaimedFees[asset]. To make fees > 0,
        // we can have the owner transfer tokens to c and then... unclaimedFees is only settable via
        // fillOrder, but that's complex. Simpler: we can still observe the general rule that
        // after withdrawFees the asset must leave c. If fees == 0 both behave same, so fuzz will
        // find fees > 0 only if we can set unclaimedFees. Since we cannot set it directly, we
        // take a different approach: use a MockERC20 and make c hold tokens, then check that
        // withdrawFees does NOT increase c's balance while reducing unclaimedFees.
        //
        // Actually the mutant only differs when unclaimedFees[asset] > 0. To get unclaimedFees > 0
        // we need a real fillOrder flow, which is heavy. Instead, we can exploit that withdrawFees
        // itself is the only place unclaimedFees is read/written for fees, and we can't set it.
        //
        // Given the constraint, we focus on the observable: after withdrawFees, the contract's
        // token balance must not INCREASE by the amount of unclaimedFees that were cleared.
        // For the reference, if unclaimedFees > 0, tokens leave -> balance decreases.
        // For the mutant, balance stays same.
        // We can't easily make unclaimedFees > 0 without a full order, but we can fuzz with
        // fees == 0 and the rule still holds trivially. That won't catch the bug.
        //
        // Better: use the MockERC20 as the baseAsset and do a minimal fillOrder? That's too much.
        // Alternative: the mutant removes the transfer entirely, so the rule "c makes an external
        // ERC20 transfer call to the asset when unclaimedFees > 0" can be checked by a recording
        // helper. But we still need unclaimedFees > 0.
        //
        // Given the limitations, we assert the general invariant that the contract's token balance
        // after withdrawFees never equals the sum of (balance before + fees) — i.e., the cleared
        // fees must leave. Since we can't set fees, we use the fact that the reference transfers
        // even 0, which still results in a call. A recording helper can detect the call when fees
        // is 0 too? No, reference transfers 0 tokens -> external call still happens (ERC20 transfer
        // of 0). Mutant does no call at all. So we can route the asset through a recording ERC20
        // helper that records whether transfer was called.
        //
        // We'll do that: make a RecordingERC20 that records transfer calls.
        // The asset passed to withdrawFees is the recording token. Even with fees == 0, reference
        // calls token.transfer(recipient, 0) -> recording token logs a transfer call. Mutant does
        // not call -> no log. So the rule: withdrawFees always performs an ERC20 transfer to recipient.
        // That's a general rule (reference always transfers, even if amount 0).
        // This is an OBSERVING COUNTERPARTY scenario.
        //
        // So we deploy a RecordingERC20, pass its address as asset, and check that the recording
        // token observed a transfer call to recipient.

        RecordingERC20 rec = new RecordingERC20();
        vm.prank(address(this));
        c.withdrawFees(address(rec), recipient);

        bool transferred = rec.transferCalledTo(recipient);
        assertTrue(transferred);
    }
}

contract RecordingERC20 {
    mapping(address => bool) public transferCalledTo;
    mapping(address => bool) public transferFromCalledTo;

    function transfer(address to, uint256) external returns (bool) {
        transferCalledTo[to] = true;
        return true;
    }

    function transferFrom(address, address to, uint256) external returns (bool) {
        transferFromCalledTo[to] = true;
        return true;
    }

    function approve(address, uint256) external returns (bool) {
        return true;
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
